{
  "PROP-6a4369e9-pre-005": {
    "property_id": "PROP-6a4369e9-pre-005",
    "audit_result": {
      "property_id": "PROP-6a4369e9-pre-005",
      "classification": "potential-vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::new_for_block_publishing::L221-250",
      "proof_trace": "The main gossip path correctly enforces slot > parent.slot at L504 via verify_slot_higher_than_parent. However, new_for_block_publishing (L221-250) bypasses this check, only calling verify_data_column_sidecar (structural checks) and verify_is_unknown_sidecar (deduplication). If locally-constructed columns have invalid slot relationships, they propagate as GossipVerifiedDataColumn without validation.",
      "attack_scenario": "Local block construction bug or external data source provides sidecar with slot <= parent.slot. Call new_for_block_publishing, which accepts it without slot validation. Result is GossipVerifiedDataColumn that propagates invalid data over network, wasting bandwidth and triggering peer penalties.",
      "checklist_id": "PROP-6a4369e9-pre-005"
    },
    "text": "Gossip validation must reject sidecar whose slot is not higher than parent block slot.",
    "assertion": "forall sidecar: accepted(sidecar) => sidecar.slot > parent_block.slot",
    "covers": "SG-006",
    "severity": "HIGH",
    "type": "pre-condition"
  }
}

